  nuit:'#0c0a13',    nuit2:'#15121f',    ombre:'#221d33',    ombre2:'#302a46',
  pierre:'#9a97b0',  pierreC:'#726f8c',  pierreS:'#4c4a63',
  os:'#f4eedd',      osC:'#d8cfb4',      osS:'#a9a086',
  peau:'#eec39d',    peauC:'#c9976f',    peauS:'#8f6446',
  sang:'#e2604c',    sangC:'#b23a32',    sangS:'#701f26',
  ambre:'#ffd27a',   ambreC:'#eda23c',   ambreS:'#a4601d',
  bois:'#c08850',    boisC:'#8e5f30',    boisS:'#57391f',
  vert:'#7fb45f',    vertC:'#4f7f45',    vertS:'#2c4a33',
  menthe:'#8ee8c8',  mentheC:'#4fae94',  mentheS:'#276b5e',
  glace:'#bfe2f0',   glaceC:'#7fb2cc',   glaceS:'#456f8e',
  spectre:'#b79ada', spectreC:'#8062ab', spectreS:'#4d3b6e',
  savon:'#cfe9ff',   savonC:'#89b9e8',   savonS:'#4a6f9e',
  mure:'#8a4fa8',    mureC:'#5a2c78',    mureS:'#2e1742',
  balle:'#dff05a',   balleC:'#b3c73a',   balleS:'#6e7c1f',
