/* ==========================================================================
   PERSONNAGES VECTORIELS
   Certains personnages ne sont pas des sprites mais des tracés, recalculés à
   chaque image. Avantage : aucune résolution, donc jamais de pixels visibles,
   et la marche s'anime par un simple paramètre au lieu d'images dessinées.
   Coût : chaque personnage doit être écrit à la main, forme par forme.
   La table VECTO associe un nom de sprite à sa fonction de tracé ; tout le
   reste du jeu continue de fonctionner comme avant pour les autres.
   ========================================================================== */
const VECTO = {};

function vForme(x, chemin, remplissage, trait, ep){
  x.beginPath(); chemin(x); x.closePath();
  if(remplissage){ x.fillStyle=remplissage; x.fill(); }
  if(trait){ x.strokeStyle=trait; x.lineWidth=ep; x.lineJoin='round'; x.stroke(); }
}
function vOvale(x, cx, cy, rx, ry, remplissage, trait, ep){
  vForme(x, (c)=>c.ellipse(cx,cy,rx,ry,0,0,6.2832), remplissage, trait, ep);
}
function vGalet(x, gx, gy, l, h, r, remplissage, trait, ep){
  vForme(x, (c)=>{
    c.moveTo(gx+r,gy);
    c.lineTo(gx+l-r,gy); c.quadraticCurveTo(gx+l,gy,gx+l,gy+r);
    c.lineTo(gx+l,gy+h-r); c.quadraticCurveTo(gx+l,gy+h,gx+l-r,gy+h);
    c.lineTo(gx+r,gy+h);   c.quadraticCurveTo(gx,gy+h,gx,gy+h-r);
    c.lineTo(gx,gy+r);     c.quadraticCurveTo(gx,gy,gx+r,gy);
  }, remplissage, trait, ep);
}

/* Ancienne version vectorielle du Galérien : marinière, bouteille, cheveux
   noirs. Remplacée par de vraies images (voir le sprite 'galerien' plus bas),
   et rangée ici hors de VECTO pour ne plus leur passer devant — le jeu consulte
   VECTO en premier. Gardée telle quelle : c'est le seul exemple de personnage
   tracé à la main, et il sert de modèle si tu veux en refaire un.
   Pour la réactiver : renommer VECTO_ARCHIVE en VECTO ci-dessous.
   cx/sol = le point où ses pieds touchent le sol ; H = sa hauteur ;
   pas = phase de marche entre 0 et 1 ; flip = tourné vers la gauche. */
const VECTO_ARCHIVE = {};
VECTO_ARCHIVE.galerien = function(x, cx, sol, H, pas, flip, alpha){
  const C={ peau:'#eec39d', peauO:'#c9976f', cheveux:'#241d2e', cheveuxC:'#3b3350',
            marine:'#3f6d96', blanc:'#eef3f7', blancO:'#c6d3dd',
            pantalon:'#2b3347', pantalonO:'#1c2231', chaussure:'#191621',
            verre:'#5d8f4e', verreH:'#9cc98a', trait:'#120e1a' };
  const t=H/100, ep=Math.max(1,H*0.022), T=C.trait;
  const bal=Math.sin(pas*Math.PI*2);
  x.save(); x.translate(cx,sol); if(flip) x.scale(-1,1);
  if(alpha!==undefined) x.globalAlpha=alpha;

  const ecart=7*t+bal*5*t;
  for(const [dx,ton] of [[-ecart,C.pantalonO],[ecart,C.pantalon]]){
    vGalet(x, dx-5.5*t, -38*t, 11*t, 33*t, 4*t, ton, T, ep);
    vGalet(x, dx-6.5*t, -6*t, 13*t, 6*t, 2.5*t, C.chaussure, T, ep);
  }

  const torse=(c)=>{
    c.moveTo(-12*t,-72*t);
    c.bezierCurveTo(-15*t,-60*t,-14*t,-48*t,-11.5*t,-37*t);
    c.lineTo(11.5*t,-37*t);
    c.bezierCurveTo(14*t,-48*t,15*t,-60*t,12*t,-72*t);
  };
  vForme(x, torse, C.blanc, T, ep);
  x.save();
  x.beginPath(); torse(x); x.closePath(); x.clip();
  x.fillStyle=C.marine;
  for(let y=-70*t; y<-36*t; y+=7.5*t) x.fillRect(-20*t,y,40*t,4*t);
  x.fillStyle='rgba(20,16,30,0.18)'; x.fillRect(5*t,-74*t,14*t,42*t);
  x.restore();
  vForme(x, torse, null, T, ep);

  const bG=-16.5*t+bal*2*t, bD=16.5*t-bal*2*t;
  vGalet(x, bG-4*t, -70*t, 8*t, 29*t, 4*t, C.blancO, T, ep);
  vGalet(x, bD-4*t, -70*t, 8*t, 29*t, 4*t, C.blanc,  T, ep);
  vOvale(x, bG, -41*t, 4.4*t, 4.4*t, C.peauO, T, ep);
  vOvale(x, bD, -41*t, 4.4*t, 4.4*t, C.peau,  T, ep);

  x.save(); x.translate(bD+5*t,-43*t); x.rotate(0.35);
  vGalet(x, -3.2*t, -20*t, 6.4*t, 12*t, 1.6*t, C.verre, T, ep*0.85);
  vGalet(x, -6*t, -10*t, 12*t, 18*t, 4*t, C.verre, T, ep*0.85);
  const a0=x.globalAlpha; x.globalAlpha=a0*0.75;
  vGalet(x, -4*t, -7*t, 3*t, 12*t, 1.5*t, C.verreH);
  x.globalAlpha=a0;
  vGalet(x, -6*t, -3*t, 12*t, 5*t, 1*t, C.blancO, T, ep*0.7);
  x.restore();

  vGalet(x, -3.5*t, -78*t, 7*t, 8*t, 2*t, C.peauO, T, ep);
  vOvale(x, 0, -87*t, 10.5*t, 11.5*t, C.peau, T, ep);
  vForme(x, (c)=>{
    c.moveTo(-10.5*t,-88*t);
    c.bezierCurveTo(-11*t,-100*t,11*t,-100*t,10.5*t,-88*t);
    c.lineTo(7.5*t,-88*t);
    c.bezierCurveTo(6.5*t,-95*t,-6.5*t,-95*t,-7.5*t,-88*t);
  }, C.cheveux, T, ep);
  const a1=x.globalAlpha; x.globalAlpha=a1*0.5;
  vForme(x, (c)=>{
    c.moveTo(-6*t,-96*t);
    c.bezierCurveTo(-2.5*t,-99*t,2.5*t,-99*t,5*t,-96*t);
    c.bezierCurveTo(1.5*t,-97*t,-2.5*t,-97*t,-6*t,-96*t);
  }, C.cheveuxC);
  x.globalAlpha=a1;
  vOvale(x, -3.9*t, -88*t, 1.3*t, 1.8*t, C.trait);
  vOvale(x,  3.9*t, -88*t, 1.3*t, 1.8*t, C.trait);
  x.globalAlpha=a1*0.6;
  vOvale(x, -6.6*t, -83.5*t, 2.1*t, 1.3*t, '#d98a7a');
  vOvale(x,  6.6*t, -83.5*t, 2.1*t, 1.3*t, '#d98a7a');
  x.globalAlpha=a1;
  x.strokeStyle=T; x.lineWidth=ep*0.8; x.lineCap='round';
  x.beginPath(); x.arc(0,-84*t,3.4*t,0.3,Math.PI-0.3); x.stroke();

  x.restore();
};

