/* Qualité adaptative (utilisée par poserSprite pour le liseré fusionné) */
const QUAL={ bloom:true, rim:true, part:1, moy:16, pire:0 };

/* Contexte 2D courant utilisé par poserSprite/eclairerSprite : la page qui
   inclut ce fichier doit l'assigner (ctx = monCanvas.getContext('2d')). */
let ctx=null;

/* --- sprites : image, silhouette blanche, version contourée --- */
const SPR={};
/* Certains sprites (les personnages jouables) sont fournis en PNG encodé en
   base64 (s.img64) plutôt qu'en grille ASCII : on les charge en image, puis
   on en dérive la silhouette blanche (flash de dégâts) une fois chargées.
   compilerSprites() renvoie donc une promesse : on ne construit le menu
   qu'une fois celle-ci résolue, pour ne jamais dessiner une image absente. */
function compilerSprites(){
  const attentes=[];
  for(const k in SPRITES){
    const s=SPRITES[k];
    if(s.img64){
      const out={img:[],blanc:[],contour:[],rim:[],w:s.img64.w,h:s.img64.h,
        cycle:s.cycle||(s.img64.frames.length>1?[0,1]:[0]),
        // poses hors du cycle de marche, toutes optionnelles : 'attaque' pour la
        // charge d'un colosse, 'repos'/'saut'/'ultime' pour un personnage jouable.
        // Pas de pose de tir : l'arme tire en continu, le personnage tressauterait.
        // 'sautille' : il avance par petits bonds au lieu de glisser.
        attaque:s.img64.attaque, repos:s.img64.repos, saut:s.img64.saut,
        ultime:s.img64.ultime, sautille:s.img64.sautille,
        // pose de réception, jouée un instant à l'atterrissage d'un saut
        atterrissage:s.img64.atterrissage,
        // taille du décor dans le monde, en unités de jeu. Sans elle, un décor
        // est dimensionné d'après la résolution de son dessin : changer la
        // finesse de l'image changerait sa taille à l'écran.
        taille:s.img64.taille};
      s.img64.frames.forEach((data,i)=>{
        const im=new Image();
        attentes.push(new Promise(res=>{ im.onload=res; }));
        im.src=data;
        // en attendant le chargement, on pointe tout vers l'image elle-même
        out.contour[i]=im; out.img[i]=im; out.blanc[i]=im; out.rim[i]=im;
      });
      SPR[k]=out;
      continue;
    }
    const out={img:[],blanc:[],contour:[],rim:[],w:0,h:0,
      cycle:s.cycle||(s.f.length>1?[0,1]:[0])};
    for(const brut of s.f){
      let lignes=brut;
      // 'miroir' : on ne dessine que la moitié gauche, l'autre est le reflet.
      // Pratique pour les créatures vues de face, et deux fois moins à écrire.
      if(s.miroir){
        const d=Math.max(...brut.map(r=>r.length));
        lignes=brut.map(r=>{ const g=r.length<d ? r+'.'.repeat(d-r.length) : r;
          return g + g.split('').reverse().join(''); });
      }
      const w=Math.max(...lignes.map(r=>r.length)), h=lignes.length;
      const rows=lignes.map(r=>r.length<w ? r+'.'.repeat(w-r.length) : r);
      const mk=()=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c;};
      const a=mk(), b=mk(), d=mk(), rm=mk();
      const xa=a.getContext('2d'), xb=b.getContext('2d'),
            xd=d.getContext('2d'), xr=rm.getContext('2d');
      const plein=(i,j)=>{ if(i<0||j<0||i>=w||j>=h) return false;
        const c=rows[j][i]; return c && c!=='.' && !!s.p[c]; };
      for(let j=0;j<h;j++) for(let i=0;i<w;i++){
        if(!plein(i,j)) continue;
        xa.fillStyle=s.p[rows[j][i]]; xa.fillRect(i,j,1,1);
        xb.fillStyle='#ffffff'; xb.fillRect(i,j,1,1);
        xd.fillStyle='rgba(7,11,16,.85)'; xd.fillRect(i,j,1,1);
        // liseré : bord exposé à la lumière, qui vient du haut-gauche
        if(!plein(i,j-1)||!plein(i-1,j)){ xr.fillStyle='#ffffff'; xr.fillRect(i,j,1,1); }
      }

      /* MODELÉ — trois passes qui donnent du volume sans redessiner :
         1. un voile clair descend du sommet,
         2. une ombre froide monte du bas,
         3. le pourtour intérieur s'assombrit pour détacher la silhouette.
         Tout est appliqué uniquement sur les pixels pleins du sprite.        */
      xa.save();
      xa.globalCompositeOperation='source-atop';
      const gH=xa.createLinearGradient(0,0,0,h);
      gH.addColorStop(0,   'rgba(255,247,228,0.20)');
      gH.addColorStop(0.40,'rgba(255,247,228,0.04)');
      gH.addColorStop(1,   'rgba(255,247,228,0)');
      xa.fillStyle=gH; xa.fillRect(0,0,w,h);
      const gB=xa.createLinearGradient(0,0,0,h);
      gB.addColorStop(0.45,'rgba(12,10,34,0)');
      gB.addColorStop(1,   'rgba(12,10,34,0.34)');
      xa.fillStyle=gB; xa.fillRect(0,0,w,h);
      xa.restore();
      // pourtour intérieur : un cran plus sombre, comme un trait d'encre
      for(let j=0;j<h;j++) for(let i=0;i<w;i++){
        if(!plein(i,j)) continue;
        if(plein(i-1,j)&&plein(i+1,j)&&plein(i,j-1)&&plein(i,j+1)) continue;
        xa.fillStyle='rgba(10,8,20,0.30)'; xa.fillRect(i,j,1,1);
      }
      const o=document.createElement('canvas'); o.width=w+2; o.height=h+2;
      const xo=o.getContext('2d'); xo.imageSmoothingEnabled=false;
      for(const [dx,dy] of [[0,1],[2,1],[1,0],[1,2]]) xo.drawImage(d,dx,dy);
      xo.drawImage(a,1,1);
      out.img.push(a); out.blanc.push(b); out.contour.push(o); out.rim.push(rm);
      out.w=w; out.h=h;
    }
    SPR[k]=out;
  }
  return Promise.all(attentes).then(()=>{
    // une fois les images chargées : silhouette blanche (flash de dégâts) et
    // liseré (bord éclairé) sont dérivés de leur canal alpha.
    for(const k in SPRITES){
      if(!SPRITES[k].img64) continue;
      const o=SPR[k];
      o.contour.forEach((im,i)=>{ o.blanc[i]=teinter(im,'#ffffff'); o.rim[i]=lisereDeImage(im); });
    }
  });
}

/* Liseré d'une image : on ne garde que le bord exposé à la lumière, qui vient
   du haut-gauche — même règle que pour les sprites ASCII. Sans ça le mode
   'rim' repeindrait toute la silhouette, et un colosse virerait au doré plein.
   L'épaisseur suit la taille de l'image, sinon le trait disparaît une fois le
   sprite réduit à l'échelle du jeu. */
function lisereDeImage(im){
  const w=im.naturalWidth||im.width, h=im.naturalHeight||im.height;
  const src=document.createElement('canvas'); src.width=w; src.height=h;
  src.getContext('2d').drawImage(im,0,0);
  const px=src.getContext('2d').getImageData(0,0,w,h).data;
  const plein=(i,j)=> i>=0 && j>=0 && i<w && j<h && px[(j*w+i)*4+3]>128;
  const ep=Math.max(1,Math.round(h/48));
  const out=document.createElement('canvas'); out.width=w; out.height=h;
  const xo=out.getContext('2d'); xo.fillStyle='#ffffff';
  for(let j=0;j<h;j++) for(let i=0;i<w;i++){
    if(!plein(i,j)) continue;
    if(!plein(i,j-ep)||!plein(i-ep,j)) xo.fillRect(i,j,1,1);
  }
  return out;
}
const SPR_PRET=compilerSprites();

/* Ajoute la couleur d'une lampe sur un sprite déjà dessiné. */
function eclairerSprite(nom,img,x,y,haut,flip,dx,dy,lampe){
  const s=SPR[nom]; if(!s||!lampe) return;
  const i=((img|0)%s.img.length+s.img.length)%s.img.length;
  const c=teinter(s.blanc[i], lampe.c);
  const ech=haut/s.h, w=c.width*ech*(dx||1), h=c.height*ech*(dy||1);
  ctx.save();
  ctx.globalCompositeOperation='lighter';
  ctx.globalAlpha=Math.min(0.5, lampe.i*0.55);
  ctx.translate(x,y); if(flip) ctx.scale(-1,1);
  ctx.drawImage(c,-w/2,-h/2,w,h);
  ctx.restore();
}

function poserSprite(nom,img,x,y,haut,flip,alpha,mode,dx,dy){
  const s=SPR[nom]; if(!s) return;
  const i=((img|0)%s.img.length+s.img.length)%s.img.length;
  const c = mode==='blanc'? s.blanc[i] : mode==='nu'? s.img[i]
          : mode==='rim'? teinter(s.rim[i],TEINTE_RIM)
          : (QUAL.rim && s.fusion && s.fusion[i]) ? s.fusion[i] : s.contour[i];
  const ech=haut/s.h, w=c.width*ech*(dx||1), h=c.height*ech*(dy||1);
  // cas courant : ni miroir ni transparence -> un seul appel, sans save/restore
  if(!flip && (alpha===undefined||alpha===1)){
    ctx.drawImage(c, x-w/2, y-h/2, w, h);
    return;
  }
  ctx.save();
  if(alpha!==undefined) ctx.globalAlpha=alpha;
  ctx.translate(x,y);
  if(flip) ctx.scale(-1,1);
  ctx.drawImage(c,-w/2,-h/2,w,h);
  ctx.restore();
}
/* Le liseré est cuit une fois pour toutes dans le sprite au début du niveau :
   ça supprime un appel de dessin par créature et par image. */
function cuireLiseres(couleur){
  for(const k in SPR){
    const s=SPR[k]; s.fusion=[];
    for(let i=0;i<s.contour.length;i++){
      const src=s.contour[i], c=document.createElement('canvas');
      c.width=src.width; c.height=src.height;
      const x=c.getContext('2d'); x.imageSmoothingEnabled=false;
      x.drawImage(src,0,0);
      x.globalAlpha=0.48; x.drawImage(teinter(s.rim[i],couleur),1,1);
      s.fusion.push(c);
    }
  }
}

/* colorisation d'une silhouette, mise en cache par couleur */
let TEINTE_RIM='#ffffff';
const CACHE_TEINTE=new Map();
function teinter(src,couleur){
  const cle=src.width+'x'+src.height+'|'+couleur+'|'+(src.__id||(src.__id=CACHE_TEINTE.size+1));
  let c=CACHE_TEINTE.get(cle);
  if(c) return c;
  c=document.createElement('canvas'); c.width=src.width; c.height=src.height;
  const x=c.getContext('2d');
  x.drawImage(src,0,0);
  x.globalCompositeOperation='source-in';
  x.fillStyle=couleur; x.fillRect(0,0,c.width,c.height);
  CACHE_TEINTE.set(cle,c);
  return c;
}
/* image d'animation à jouer selon le cycle défini par le sprite */
function imageCycle(nom,pas){
  const c=SPR[nom]&&SPR[nom].cycle; if(!c||!c.length) return 0;
  return c[((pas|0)%c.length+c.length)%c.length];
}

/* Portrait d'un sprite ou personnage vectoriel, mis à l'échelle dans une
   boîte fixe sans déformation (le plus petit des deux rapports gagne). */
/* Le portrait doit tenir dans une boîte fixe SANS être déformé : on prend
   la plus petite des deux échelles. Sinon un sprite large comme la Porsche
   déborde de sa carte et écrase le texte. */
function vignette(nom, boiteH, boiteL){
  if(VECTO[nom]){                       // personnage vectoriel : on le trace
    const h=boiteH||64, l=boiteL||Math.round(h*0.78);
    const c=document.createElement('canvas'); c.width=l; c.height=h; c.className='vg';
    VECTO[nom](c.getContext('2d'), l/2, h-1, h*0.96, 0.25, false, 1);
    return c;
  }
  const s=SPR[nom], src=s.contour[s.repos!=null?s.repos:0];
  // On cadre sur les pixels réellement dessinés, pas sur l'image entière : une
  // image d'action réserve de la place pour ce qu'elle projette (bouteilles,
  // billets), et sans ce recadrage le portrait du menu serait tout petit,
  // perdu au milieu du vide.
  const vue=zoneVisible(src);
  const maxH=boiteH||64, maxL=boiteL||Math.round(maxH*0.78);
  const ech=Math.min(maxH/vue.h, maxL/vue.l);
  const c=document.createElement('canvas');
  c.width=Math.max(1,Math.round(vue.l*ech));
  c.height=Math.max(1,Math.round(vue.h*ech));
  c.className='vg';
  const x=c.getContext('2d'); x.imageSmoothingEnabled=false;
  x.drawImage(src, vue.x, vue.y, vue.l, vue.h, 0, 0, c.width, c.height);
  return c;
}

/* Boîte des pixels non transparents d'une image, calculée une fois et retenue. */
const CACHE_ZONE=new Map();
function zoneVisible(src){
  const cle=src.__zone||(src.__zone='z'+CACHE_ZONE.size);
  let z=CACHE_ZONE.get(cle);
  if(z) return z;
  const l=src.naturalWidth||src.width, h=src.naturalHeight||src.height;
  const cv=document.createElement('canvas'); cv.width=l; cv.height=h;
  const ct=cv.getContext('2d'); ct.drawImage(src,0,0);
  const px=ct.getImageData(0,0,l,h).data;
  let x0=l, y0=h, x1=-1, y1=-1;
  for(let j=0;j<h;j++) for(let i=0;i<l;i++){
    if(px[(j*l+i)*4+3]<40) continue;
    if(i<x0)x0=i; if(i>x1)x1=i; if(j<y0)y0=j; if(j>y1)y1=j;
  }
  z = x1<0 ? {x:0,y:0,l,h} : {x:x0, y:y0, l:x1-x0+1, h:y1-y0+1};
  CACHE_ZONE.set(cle,z);
  return z;
}
